// isPathTarget tells a filesystem path from an image reference such as
// "registry/ns/app:1.2", which ShortPath would mangle.
func isPathTarget(target string) bool {
	return filepath.IsAbs(target) || strings.HasPrefix(target, "~")
}

// RowStatusLine composes the footer line for a selected row: its detail, then
// the batch progress, on one line of at most width columns. The progress is
// what gives way last; the detail is dropped whole when fewer than
// minDetailCols are left for it (or fewer than it needs, if it is shorter).
func RowStatusLine(detail RowDetail, progress string, width int) string {
	switch {
	case width <= 0:
		return ""
	case detail.IsZero():
		return theme.TruncateWidth(progress, width)
	case progress == "":
		return detail.fit(width)
	}
	room := width - theme.StringWidth(rowSeparator) - theme.StringWidth(progress)
	if room < min(minDetailCols, theme.StringWidth(detail.String())) {
		return theme.TruncateWidth(progress, width)
	}
	return detail.fit(room) + rowSeparator + progress
}
}

// agentDetail is what the footer says about the selected agent: its state in
// words, since the dot only repeats it in colour. It is empty off the Agents
// tab and when no row is selected.
func (m Model) agentDetail() components.RowDetail {
	if m.level != levelAgents || m.tab != tabAgents {
		return components.RowDetail{}
	}
	r, ok := m.agentTable.Selected()
	if !ok {
		return components.RowDetail{}
	}
	return components.DescribeRow(components.RowQuery{
		Observed: r.state.indicator(), ObservedText: agentStateText(r),
	}).Detail
}

// agentStateText is the sentence for one agent's state.
func agentStateText(r agentRow) string {
	switch r.state {
	case stateRunning:
		return "Agent running — last transcript line " + theme.TimeAgo(r.LastActivity)
	case stateIdle:
		return "Agent idle — last transcript line " + theme.TimeAgo(r.LastActivity)
	case stateDone:
		return "Agent done — ran " + formatDuration(r.Duration(), !r.FirstActivity.IsZero())
	case stateUnknown:
		if r.Main {
			return "Agent state unknown — updates are paused"
		}
		return "Agent state unknown — transcript has no end marker"
	}
	return ""
}
